('00000000-0000-0000-0000-000000000000', 'Kann ich als Azubi vom Kündigungsschutzgesetz profitieren?', 2, '[{"text": "Ja", "correct": true, "because": "Gilt auch für Azubis"}, {"text": "Nein", "correct": false, "because": "Azubis eingeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss mein Betrieb immer das Kündigungsschutzgesetz beachten?', 2, '[{"text": "Nein", "correct": true, "because": "Nur ab 10+ Mitarbeitern"}, {"text": "Ja", "correct": false, "because": "Schwelle erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Schützt das Kündigungsschutzgesetz mich vor jeder Kündigung?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei sozialer Ungerechtigkeit"}, {"text": "Ja", "correct": false, "because": "Begründung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich wegen Krankheit unter dem KSchG gekündigt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Krankheit allein nicht ausreichend"}, {"text": "Ja", "correct": false, "because": "Soziale Rechtfertigung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Gilt das KSchG in der Probezeit?', 2, '[{"text": "Nein", "correct": true, "because": "Probezeit ausgenommen"}, {"text": "Ja", "correct": false, "because": "Erst nach 6 Monaten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ich beim Arbeitsgericht gegen eine Kündigung klagen?', 2, '[{"text": "Ja", "correct": true, "because": "KSchG erlaubt Klage"}, {"text": "Nein", "correct": false, "because": "Rechtsschutz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Betrieb mich vor Kündigung anhören?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Betriebsrat wird angehört"}, {"text": "Ja", "correct": false, "because": "Keine direkte Pflicht"}]'),
