-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Wann gilt das Kündigungsschutzgesetz für mich?', 2, '[{"text": "Nach 6 Monaten", "correct": true, "because": "Mindestdauer KSchG"}, {"text": "Ab Tag 1", "correct": false, "because": "Probezeit ausgenommen"}, {"text": "Nach 1 Jahr", "correct": false, "because": "Zu lang"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin kündigt mich wegen Streit. Was sagt das KSchG?', 3, '[{"text": "Soziale Rechtfertigung nötig", "correct": true, "because": "KSchG-Anforderung"}, {"text": "Immer erlaubt", "correct": false, "because": "Schutz gilt"}, {"text": "Nie erlaubt", "correct": false, "because": "Abhängig von Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss der Betrieb laut KSchG vor meiner Kündigung tun?', 2, '[{"text": "Betriebsrat anhören", "correct": true, "because": "Pflicht bei Kündigung"}, {"text": "Mir Bescheid sagen", "correct": false, "because": "Nur schriftlich nötig"}, {"text": "Nichts", "correct": false, "because": "Anhörung vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter kündigt mich. Was kann ich tun?', 3, '[{"text": "Kündigungsschutzklage erheben", "correct": true, "because": "KSchG erlaubt"}, {"text": "Nichts", "correct": false, "because": "Rechtsschutz möglich"}, {"text": "Chef anrufen", "correct": false, "because": "Keine Lösung"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was regelt das Kündigungsschutzgesetz?', 4, '[{"text": "Kündigungsfristen", "correct": true, "because": "Teil des KSchG"}, {"text": "Soziale Rechtfertigung", "correct": true, "because": "Kernvorschrift"}, {"text": "Betriebsratsanhörung", "correct": true, "because": "Pflicht"}, {"text": "Urlaubsanspruch", "correct": false, "because": "BUrlG"}]'),
('00000000-0000-0000-0000-000000000000', 'Wann greift das KSchG nicht?', 3, '[{"text": "In der Probezeit", "correct": true, "because": "Bis 6 Monate ausgenommen"}, {"text": "Bei Kleinbetrieben", "correct": true, "because": "Unter 10 Mitarbeiter"}, {"text": "Bei Krankheit", "correct": true, "because": "Sonderregelung"}, {"text": "Immer", "correct": false, "because": "Bedingungen gelten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Streit über meine Kündigung. Was sagt das KSchG?', 3, '[{"text": "Kündigung muss begründet sein", "correct": true, "because": "Soziale Rechtfertigung"}, {"text": "Fristen einhalten", "correct": true, "because": "Vorgeschrieben"}, {"text": "Klage möglich", "correct": true, "because": "Rechtsschutz"}, {"text": "Chef entscheidet allein", "correct": false, "because": "Anhörung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte gibt mir das KSchG?', 4, '[{"text": "Schutz vor willkürlicher Kündigung", "correct": true, "because": "Hauptziel"}, {"text": "Klagefrist von 3 Wochen", "correct": true, "because": "Vorgeschrieben"}, {"text": "Weiterbeschäftigung möglich", "correct": true, "because": "Gerichtsurteil"}, {"text": "Mehr Urlaub", "correct": false, "because": "Kein Bezug"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das KSchG schützt mich nach 6 Monaten. b) Es gilt in der Probezeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "6 Monate ja, Probezeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das KSchG verlangt eine Begründung. b) Es gilt für Kleinbetriebe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Begründung ja, Kleinbetriebe nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ich kann gegen Kündigung klagen. b) Das KSchG regelt meinen Urlaub.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klage ja, Urlaub nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das KSchG schützt vor ungerechter Kündigung. b) Es gilt nur für Vollzeitkräfte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, alle betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

